INSERT OR IGNORE INTO questions (id, subject, section, topic, integrates_with, difficulty, skill_measured, skill_type, format, question, choices, answer, solution_steps, common_mistakes)
VALUES ('bio-cell-001', 'bio', 'หน่วยพื้นฐานของสิ่งมีชีวิต', 'โครงสร้างและการทำงานของเซลล์', '[]', 'hard', 'คำนวณศักย์น้ำ (water potential) ของเซลล์พืชจากศักย์แรงดันและศักย์ออสโมซิส (ระดับค่าย สอวน)', NULL, 'mc5', 'เซลล์พืชเซลล์หนึ่งมีศักย์ออสโมซิส (solute potential) เท่ากับ -0.8 MPa และศักย์แรงดัน (pressure potential) เท่ากับ +0.3 MPa ศักย์น้ำ (water potential) รวมของเซลล์นี้เท่ากับเท่าใด', '["-1.1 MPa", "-0.5 MPa", "+0.5 MPa", "+0.8 MPa", "+1.1 MPa"]', '-0.5 MPa', '["ศักย์น้ำ Ψ = Ψp + Ψs = 0.3 + (-0.8) = -0.5 MPa"]', '["บวกค่าสัมบูรณ์ทั้งสองเข้าด้วยกันโดยลืมเครื่องหมายลบของศักย์ออสโมซิส"]');
INSERT OR IGNORE INTO questions (id, subject, section, topic, integrates_with, difficulty, skill_measured, skill_type, format, question, choices, answer, solution_steps, common_mistakes)
VALUES ('bio-respiration-001', 'bio', 'หน่วยพื้นฐานของสิ่งมีชีวิต', 'หายใจระดับเซลล์', '[]', 'medium', 'คำนวณผลได้สุทธิของ ATP จากกระบวนการไกลโคไลซิส (ระดับค่าย สอวน)', NULL, 'mc5', 'ในกระบวนการไกลโคไลซิส จากกลูโคส 1 โมเลกุล มีการสร้าง ATP แบบ substrate-level phosphorylation ทั้งหมด 4 โมเลกุล แต่ใช้ ATP ไปในขั้นตอนเริ่มต้น 2 โมเลกุล ผลได้สุทธิของ ATP จากไกลโคไลซิสเท่ากับกี่โมเลกุล', '["0", "1", "2", "4", "6"]', '2', '["ผลได้สุทธิ = ATP ที่สร้างได้ - ATP ที่ใช้ไป = 4-2 = 2 โมเลกุล"]', '["ตอบ ATP ที่สร้างได้ทั้งหมด (4) โดยลืมหักส่วนที่ใช้ลงทุนไปก่อน"]');
INSERT OR IGNORE INTO questions (id, subject, section, topic, integrates_with, difficulty, skill_measured, skill_type, format, question, choices, answer, solution_steps, common_mistakes)
VALUES ('bio-proteinsynthesis-001', 'bio', 'พันธุศาสตร์และวิวัฒนาการ', 'สารพันธุกรรมและการสังเคราะห์โปรตีน', '[]', 'hard', 'คำนวณจำนวนกรดอะมิโนจากความยาวสาย mRNA (ระดับค่าย สอวน)', NULL, 'mc5', 'สาย mRNA เส้นหนึ่งมีความยาวทั้งหมด 303 นิวคลีโอไทด์ ซึ่งรวมโคดอนเริ่มต้นและโคดอนหยุดไว้ด้วย (ไม่มีส่วนที่ไม่ถูกแปลรหัสอื่น) โพลีเพปไทด์ที่ได้จะมีกรดอะมิโนกี่ตัว', '["99", "100", "101", "102", "303"]', '100', '["จำนวนโคดอนทั้งหมด = 303/3 = 101 โคดอน", "โคดอนหยุดไม่ได้กำหนดกรดอะมิโน จึงหักออก 1 โคดอน: 101-1 = 100 กรดอะมิโน"]', '["ลืมหักโคดอนหยุดออกจากจำนวนโคดอนทั้งหมด"]');
INSERT OR IGNORE INTO questions (id, subject, section, topic, integrates_with, difficulty, skill_measured, skill_type, format, question, choices, answer, solution_steps, common_mistakes)
VALUES ('bio-transpiration-001', 'bio', 'โครงสร้างและการทำงานของส่วนต่างๆ ในพืช', 'การแลกเปลี่ยนแก๊ส การคายน้ำ และการลำเลียงในพืช', '[]', 'medium', 'คำนวณอัตราการคายน้ำต่อพื้นที่ใบจากข้อมูลการทดลองโพโทมิเตอร์ (ระดับค่าย สอวน)', NULL, 'mc5', 'การทดลองด้วยโพโทมิเตอร์พบว่าพืชดูดน้ำไป 15 มิลลิลิตร ภายในเวลา 30 นาที โดยพืชนี้มีพื้นที่ใบทั้งหมด 500 ตารางเซนติเมตร อัตราการคายน้ำต่อพื้นที่ใบเท่ากับกี่มิลลิลิตรต่อตารางเซนติเมตรต่อชั่วโมง', '["0.03", "0.06", "0.12", "0.15", "0.30"]', '0.06', '["อัตราการดูดน้ำต่อชั่วโมง = 15 มล. / (30/60 ชม.) = 30 มล./ชม.", "อัตราต่อพื้นที่ใบ = 30/500 = 0.06 มล./ตร.ซม./ชม."]', '["ลืมแปลงเวลาจากนาทีเป็นชั่วโมงก่อนหาอัตราต่อชั่วโมง"]');
INSERT OR IGNORE INTO questions (id, subject, section, topic, integrates_with, difficulty, skill_measured, skill_type, format, question, choices, answer, solution_steps, common_mistakes)
VALUES ('bio-population-001', 'bio', 'ความหลากหลายทางชีวภาพและสิ่งแวดล้อม', 'ประชากร', '[]', 'hard', 'คำนวณขนาดประชากรจากแบบจำลองการเติบโตแบบเอกซ์โพเนนเชียล (ระดับค่าย สอวน)', NULL, 'mc5', 'ประชากรชนิดหนึ่งเริ่มต้นมี 200 ตัว เติบโตแบบเอกซ์โพเนนเชียลด้วยอัตราการเติบโตจำเพาะ r=0.1 ต่อปี (ไม่มีปัจจัยจำกัด) โดยใช้สมการ N(t)=N₀e^(rt) ประชากรหลังจากผ่านไป 10 ปี มีขนาดประมาณเท่าใด', '["400 ตัว", "450 ตัว", "500 ตัว", "544 ตัว", "600 ตัว"]', '544 ตัว', '["N(10) = 200×e^(0.1×10) = 200×e¹ = 200×2.718 ≈ 544 ตัว"]', '["ใช้แบบจำลองการเติบโตเชิงเส้นแทนเอกซ์โพเนนเชียล (200+200×0.1×10=400) ทำให้คำตอบผิด"]');
INSERT OR IGNORE INTO questions (id, subject, section, topic, integrates_with, difficulty, skill_measured, skill_type, format, question, choices, answer, solution_steps, common_mistakes)
VALUES ('bio-excretion-001', 'bio', 'ระบบและการทำงานของสัตว์และมนุษย์', 'ระบบขับถ่าย', '[]', 'medium', 'คำนวณร้อยละการดูดกลับของสารกรองที่ไต (ระดับค่าย สอวน)', NULL, 'mc5', 'ไตกรองเลือดได้สารกรอง (filtrate) ประมาณ 180 ลิตรต่อวัน แต่ขับปัสสาวะออกมาจริงเพียง 1.5 ลิตรต่อวัน ร้อยละของสารกรองที่ถูกดูดกลับ (reabsorption) เท่ากับเท่าใด (ปัดเศษทศนิยม 1 ตำแหน่ง)', '["95.0%", "97.5%", "99.0%", "99.2%", "99.9%"]', '99.2%', '["ปริมาณที่ถูกดูดกลับ = 180-1.5 = 178.5 ลิตร", "ร้อยละการดูดกลับ = 178.5/180×100 ≈ 99.2%"]', '["คำนวณร้อยละของปัสสาวะที่ขับออก (1.5/180) แล้วเข้าใจผิดว่าเป็นคำตอบ แทนที่จะหาส่วนที่ดูดกลับ"]');
